CREATE INDEX IF NOT EXISTS idx_daily_token_claims_user_date ON daily_token_claims(user_id, claim_date);
CREATE INDEX IF NOT EXISTS idx_daily_token_claims_wallet ON daily_token_claims(wallet_address);
DO $$
BEGIN
