  ) THEN
    CREATE TRIGGER trigger_update_images_updated_at
    BEFORE UPDATE ON public.images
    FOR EACH ROW
    EXECUTE FUNCTION public.update_images_updated_at();
    
    RAISE NOTICE '✅ Trigger para updated_at en images creado';
  END IF;
END $$;

