              AND table_name = 'couple_disputes'
              AND column_name = 'frozen_assets_snapshot'
        ) THEN
            COMMENT ON COLUMN couple_disputes.frozen_assets_snapshot IS 'Snapshot JSONB de activos congelados como evidencia';
        END IF;

        IF EXISTS (
