-- ============================================================================

-- Tabla de auditoría de seguridad
CREATE TABLE IF NOT EXISTS public.security_audit_log (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID,
    ip_address TEXT,
    action TEXT,
    resource TEXT,
    details JSONB,
    severity TEXT DEFAULT 'info',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
