  ADD COLUMN IF NOT EXISTS her_name text,
  ADD COLUMN IF NOT EXISTS her_age integer,
  ADD COLUMN IF NOT EXISTS her_gender text,
  ADD COLUMN IF NOT EXISTS her_interests text[];

DO $$
