        ALTER TABLE public.couple_profiles ADD COLUMN agreement_id UUID REFERENCES public.couple_agreements(id) ON DELETE SET NULL;
    END IF;
    
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns 
