-- Función para actualizar updated_at (debe estar antes de los triggers)
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- ============================================================================
-- SECCIÓN 3: TABLAS PRINCIPALES (CREATE TABLE IF NOT EXISTS)
-- ============================================================================

-- Tabla: profiles (base)
CREATE TABLE IF NOT EXISTS profiles (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
    first_name TEXT,
    last_name TEXT,
    display_name TEXT,
    email TEXT UNIQUE,
    phone TEXT,
    age INTEGER,
    gender TEXT,
    bio TEXT,
    location TEXT,
    city TEXT,
    latitude NUMERIC,
    longitude NUMERIC,
    avatar_url TEXT,
    cover_image_url TEXT,
    interests TEXT[] DEFAULT '{}',
    looking_for TEXT[] DEFAULT '{}',
    experience_level TEXT DEFAULT 'beginner',
    relationship_type TEXT DEFAULT 'dating',
    is_verified BOOLEAN DEFAULT FALSE,
    is_premium BOOLEAN DEFAULT FALSE,
    is_demo BOOLEAN DEFAULT FALSE,
    is_active BOOLEAN DEFAULT TRUE,
    is_online BOOLEAN DEFAULT FALSE,
    last_active TIMESTAMPTZ,
    role user_role DEFAULT 'user',
    profile_type TEXT DEFAULT 'single',
    preferences JSONB DEFAULT '{}'::jsonb,
    statistics JSONB DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Tabla: couple_profiles
CREATE TABLE IF NOT EXISTS couple_profiles (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    partner_1_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
    partner_2_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
    couple_name TEXT,
    display_name TEXT,
    bio TEXT,
    interests TEXT[] DEFAULT '{}',
    location TEXT,
    latitude NUMERIC,
    longitude NUMERIC,
    age_range_min INTEGER,
    age_range_max INTEGER,
    looking_for TEXT[] DEFAULT '{}',
    experience_level TEXT DEFAULT 'beginner',
    relationship_type TEXT DEFAULT 'dating',
    relationship_duration INTEGER,
    is_active BOOLEAN DEFAULT TRUE,
    is_verified BOOLEAN DEFAULT FALSE,
    is_premium BOOLEAN DEFAULT FALSE,
    is_demo BOOLEAN DEFAULT FALSE,
    status TEXT DEFAULT 'ACTIVE',
    photos TEXT[] DEFAULT '{}',
    videos TEXT[] DEFAULT '{}',
    preferences JSONB DEFAULT '{}'::jsonb,
    statistics JSONB DEFAULT '{}'::jsonb,
    compatibility_factors JSONB DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Tabla: matches
CREATE TABLE IF NOT EXISTS matches (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    profile_id_1 UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
    profile_id_2 UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
    status match_status DEFAULT 'pending',
    compatibility_score DECIMAL(5,2),
    matched_at TIMESTAMPTZ DEFAULT NOW(),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(profile_id_1, profile_id_2)
);

-- Tabla: reports
CREATE TABLE IF NOT EXISTS reports (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    reporter_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
    reported_user_id UUID REFERENCES profiles(id) ON DELETE SET NULL,
    reported_couple_id UUID REFERENCES couple_profiles(id) ON DELETE SET NULL,
    reason TEXT NOT NULL,
    description TEXT,
    status report_status DEFAULT 'pending',
    priority TEXT DEFAULT 'medium',
    assigned_to UUID REFERENCES auth.users(id),
    ai_classified BOOLEAN DEFAULT FALSE,
    queue_position INTEGER,
    reviewing TEXT DEFAULT 'pending',
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Tabla: user_wallets
CREATE TABLE IF NOT EXISTS user_wallets (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    user_id UUID NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE,
    wallet_address VARCHAR(255) UNIQUE,
    cmpx_balance DECIMAL(18,8) DEFAULT 0,
    gtk_balance DECIMAL(18,8) DEFAULT 0,
    nft_count INTEGER DEFAULT 0,
    total_earned DECIMAL(18,8) DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Tabla: chat_rooms
CREATE TABLE IF NOT EXISTS chat_rooms (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    name TEXT,
    description TEXT,
    created_by UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
    is_private BOOLEAN DEFAULT FALSE,
    participants UUID[] DEFAULT '{}',
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Tabla: messages
CREATE TABLE IF NOT EXISTS messages (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    chat_room_id UUID NOT NULL REFERENCES chat_rooms(id) ON DELETE CASCADE,
    sender_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
    content TEXT NOT NULL,
    message_type TEXT DEFAULT 'text',
    media_url TEXT,
    is_edited BOOLEAN DEFAULT FALSE,
    edited_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Tabla: notifications
CREATE TABLE IF NOT EXISTS notifications (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    user_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    message TEXT,
    notification_type TEXT,
    related_user_id UUID REFERENCES profiles(id) ON DELETE SET NULL,
    is_read BOOLEAN DEFAULT FALSE,
    read_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Tabla: invitations
CREATE TABLE IF NOT EXISTS invitations (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    inviter_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
    invitee_email TEXT NOT NULL,
