ALTER TABLE consent_evidence ENABLE ROW LEVEL SECURITY;
CREATE POLICY "consent_evidence_view_own" ON consent_evidence
  FOR SELECT
  USING (
    EXISTS (
      SELECT 1 FROM user_consents 
      WHERE id = consent_id 
      AND user_id = auth.uid()
    )
  );
-- Comentarios
