    BEFORE UPDATE ON user_nfts
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER update_daily_token_claims_updated_at
    BEFORE UPDATE ON daily_token_claims
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

